      // ... implementation of translateText ...
      return {
        name: "translate_text",
        args: {
          text,
          target_language
        }
      };
    };

    // Qwen function: calculator(expression)
    const calculator = (expression) => {
      // ... implementation of calculator ...
      return {
        name: "calculator",
        args: {
          expression
        }
      };
    };

    // Qwen function: search_documents(query)
    const searchDocuments = (query) => {
      // ... implementation of searchDocuments ...
      return {
        name: "search_documents",
        args: {
          query
        }
      };
    };

    // Example usage of the registered functions
    const inputQuery = "Mia Lopez";

    const searchOutput = searchContacts(inputQuery);
