    const calcOutput = calculator(inputQuery);
    console.log(`${calcOutput.name}:`, JSON.stringify(calcOutput));

    const docQuery = "an office";
    const searchDocOutput = searchDocuments(docQuery);
    console.log(`${searchDocOutput.name}:`, JSON.stringify(searchDocOutput));
  </script>
</body>
