function set_reminder() {
  const { text, time } = arguments[0];
  const reminder_time = new Date(time);
  const now = new Date();
  const time_diff = moment.duration(reminder_time).diff(now);
  const notification_interval = Math.round(time_diff / 1000);
  const notification_text = `Time to ${text}! Reminder in ${notification_interval} seconds`;
  const notification_message = generateEmailMessage('Reminder', notification_text, 'Ffpatrick@example.com');
  const display_notification = setInterval(() => {
    if (notification_interval <= 0) {
      clearInterval(display_notification);
      doNotification(notification_message);
      return;
    }
    notification_interval--;
    const remaining_time = notification_interval + ' seconds left';
    console.log(remaining_time);
    updateNotification(notification_text, notification_message);
  }, 1000);
}

function doNotification(message) {
